INSERT INTO {} (id, row_count)
SELECT 1, COUNT(*)::bigint FROM {}
ON CONFLICT (id) DO NOTHING

CREATE OR REPLACE FUNCTION public.{fn_insert}() RETURNS trigger AS $$
BEGIN
    UPDATE {stats}
    SET row_count = row_count + (SELECT COUNT(*)::bigint FROM inserted)
    WHERE id = 1;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION public.{fn_delete}() RETURNS trigger AS $$
BEGIN
    UPDATE {stats}
    SET row_count = GREATEST(
        row_count - (SELECT COUNT(*)::bigint FROM deleted),
        0
    )
    WHERE id = 1;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql

CREATE TRIGGER {trigger_insert}
AFTER INSERT ON {table}
REFERENCING NEW TABLE AS inserted
FOR EACH STATEMENT EXECUTE FUNCTION public.{fn_insert}()

CREATE TRIGGER {trigger_delete}
AFTER DELETE ON {table}
REFERENCING OLD TABLE AS deleted
FOR EACH STATEMENT EXECUTE FUNCTION public.{fn_delete}()

DO $$
DECLARE
    gen text;
BEGIN
    SELECT a.attgenerated INTO gen
    FROM pg_attribute a
    JOIN pg_class c ON c.oid = a.attrelid
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relname = '{table_only}'
      AND a.attname = 'content_tsv'
      AND a.attnum > 0
      AND NOT a.attisdropped;

    IF gen IS NULL THEN
        ALTER TABLE {table}
        ADD COLUMN content_tsv TSVECTOR;
    ELSIF gen <> '' THEN
        ALTER TABLE {table} DROP COLUMN content_tsv;
        ALTER TABLE {table}
        ADD COLUMN content_tsv TSVECTOR;
    END IF;
END $$;

